const fs = await import('node:fs');
const path = await import('node:path');
const image_path = process.env.INPUT_IMAGE_PATH;
const output_path = process.env.OUTPUT_PDF_PATH;
if (!image_path || !output_path) {
  throw new Error('Missing INPUT_IMAGE_PATH or OUTPUT_PDF_PATH');
}
if (!fs.existsSync(image_path)) {
  throw new Error(`Image file not found: ${image_path}`);
}
const outDir = path.dirname(output_path);
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}
globalThis.image_path = image_path;
globalThis.output_path = output_path;

const result = {
  pdf_path: globalThis.pdf_path,
  size_bytes: globalThis.size_bytes
};
